#!/usr/bin/env bash
# Patch 104 voor hrmforce-site: Italiaans (it) en Portugees (pt) erbij (02-11-2026).
#
#   bash toepassen-104.sh
#
# Wat dit script doet, in deze volgorde:
#  1. Zet de code klaar voor de twee talen: talenlijst en taalnamen (Italiano,
#     Português), vlaggen, de drie lijsten onder functions/, betaal-locale voor
#     Mollie (it_IT, pt_PT, en meteen ook pl_PL, da_DK, sv_SE), redirects,
#     cookiebanner en datumnotatie. Portugees vertaalt naar de variant van
#     Portugal (PT-PT).
#  2. Bouwt de oefenbanken in acht talen. Alle oefenvragen en de 274
#     vragenlijststellingen zijn met de hand in het Italiaans en Portugees gezet,
#     dus hier gaat niets door DeepL.
#  3. Taalnamen, segmentnamen, aanhef en onderwerp van de mails en de labels uit
#     de prijstabel staan al met de hand in de vertaalbestanden. DeepL slaat ze over.
#  4. Vraagt je DeepL-sleutel (als DEEPL_API_KEY nog niet gezet is) en vertaalt
#     de sitetekst (ca. 364.000 tekens per taal) en de interfacewoorden.
#     Samen ca. 750.000 tekens, op DeepL Pro ongeveer EUR 15.
#  5. Schrijft de mailteksten, bouwt de site en draait de taalcontrole.
#  6. Zet alles op de branch talen-it-pt en pusht die. Main blijft ongemoeid:
#     Claude kijkt de vertaling eerst na, daarna volgt een korte patch die de
#     branch op main zet en eventuele correcties meeneemt.
#
# Duur: ongeveer 10 tot 15 minuten (vertalen en bouwen).
set -euo pipefail
cd "$(dirname "$0")"
[ -f functions/_middleware.js ] || { echo "Draai dit vanuit de hoofdmap van hrmforce-site."; exit 1; }

BRANCH=talen-it-pt
git checkout -q main
git pull -q --ff-only
git checkout -q -B "$BRANCH"

echo "== 1/6 code klaarzetten =="
cat > /tmp/104.b64 <<'B64EOF'
