git commit -q -F - <<'MSGEOF'
Italiaans en Portugees, inclusief oefenbanken

Twee nieuwe talen volgens TAAL-TOEVOEGEN.md. Italië en Portugal plus
Brazilië geven de meeste vertoningen in Search Console van de landen zonder
eigen taalversie (aug t/m okt 2026). Portugees vertaalt naar PT-PT.

De oefenbanken en de 274 vragenlijststellingen staan met de hand in beide
talen in de generatoren, net als de taalnamen, segmentnamen, aanhef en de
labels uit de prijstabel in de vertaalbestanden. De sitetekst en de
interfacewoorden komen uit DeepL. Mollie krijgt voortaan de juiste taal
voor Pools, Deens, Zweeds, Italiaans en Portugees.

